package com.rustyledger.legacy;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.List;

public class TransactionManager implements Ledger {
    private final AccountRegistry accounts = new AccountRegistry();
    private final TransactionRegistry txs = new TransactionRegistry();
    private final AuditLog audit = new AuditLog();
    private final StatsRegistry stats = new StatsRegistry();
    private final UsageTracker usage = new UsageTracker();
    private final CurrencyService currencyService = new CurrencyService();
    private final FeeService feeService = new FeeService();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|"))
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier))
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(currency))
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?"))
            throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        if (accounts.contains(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.add(id, tier, currency, new BigDecimal(openingBalance).setScale(2));
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return audit.getAudit(); }

    public String dailyReport(String date) { return stats.getReport(date); }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty())
            return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = getWant(verb);
        if (want == -1) return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(verb, null, "BAD_DATE", date);
        if (verb.equals("REVERSE")) return doReverse(date, f[2]);
        return processAction(verb, date, f);
    }

    private int getWant(String v) {
        return switch (v) { case "TRANSFER" -> 6; case "WITHDRAW", "DEPOSIT" -> 4; case "REVERSE" -> 3; default -> -1; };
    }

    private String processAction(String v, String d, String[] f) {
        String amtT = v.equals("TRANSFER") ? f[4] : f[3];
        if (!amtT.matches("\\d+(\\.\\d{1,2})?")) return reject(v, d, "BAD_AMOUNT", amtT);
        BigDecimal amt = new BigDecimal(amtT).setScale(2);
        if (amt.signum() <= 0) return reject(v, d, "BAD_AMOUNT", amtT);
        if (v.equals("TRANSFER")) return doTransfer(d, f[2], f[3], amt, f[5]);
        if (v.equals("WITHDRAW")) return doWithdraw(d, f[2], amt);
        return doDeposit(d, f[2], amt);
    }

    private String doTransfer(String d, String fromId, String toId, BigDecimal amt, String cur) {
        Account from = accounts.get(fromId);
        Account to = accounts.get(toId);
        if (from == null) return reject("TRANSFER", d, "UNKNOWN_ACCOUNT", fromId);
        if (to == null) return reject("TRANSFER", d, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", d, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(cur)) return reject("TRANSFER", d, "CURRENCY_MISMATCH", fromId + " holds " + from.currency);
        BigDecimal fee = feeService.calculate(from.tier, amt);
        String rej = checkLimitAndFunds(d, from, amt, fee);
        if (rej != null) {
            String[] p = rej.split(": ", 2);
            return reject("TRANSFER", d, p[0], p[1]);
        }
        BigDecimal cred = currencyService.convert(amt, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amt.add(fee));
        to.balance = to.balance.add(cred);
        usage.add(fromId, d, amt);
        String txId = txs.add(new Transaction("TRANSFER", d, fromId, toId, amt, from.currency, fee, cred, false));
        stats.addFee(d, from.currency, fee);
        return accept("TRANSFER", d, txId, "fee=" + fee + " " + from.currency);
    }

    private String doWithdraw(String d, String id, BigDecimal amt) {
        Account a = accounts.get(id);
        if (a == null) return reject("WITHDRAW", d, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = a.tier.equals("STANDARD") ? new BigDecimal("1.00") : BigDecimal.ZERO;
        String rej = checkLimitAndFunds(d, a, amt, fee);
        if (rej != null) {
            String[] p = rej.split(": ", 2);
            return reject("WITHDRAW", d, p[0], p[1]);
        }
        a.balance = a.balance.subtract(amt.add(fee));
        usage.add(id, d, amt);
        String txId = txs.add(new Transaction("WITHDRAW", d, id, "", amt, a.currency, fee, amt, false));
        stats.addFee(d, a.currency, fee);
        return accept("WITHDRAW", d, txId, "fee=" + fee + " " + a.currency);
    }

    private String doDeposit(String d, String id, BigDecimal amt) {
        Account a = accounts.get(id);
        if (a == null) return reject("DEPOSIT", d, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amt);
        String txId = txs.add(new Transaction("DEPOSIT", d, id, "", amt, a.currency, BigDecimal.ZERO, amt, false));
        return accept("DEPOSIT", d, txId, "fee=0.00 " + a.currency);
    }

    private String doReverse(String d, String txId) {
        Transaction tx = txs.get(txId);
        if (tx == null) return reject("REVERSE", d, "UNKNOWN_TX", txId);
        if (!tx.verb.equals("TRANSFER")) return reject("REVERSE", d, "NOT_REVERSIBLE", txId + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", d, "ALREADY_REVERSED", txId);
        if (!tx.date.equals(d)) return reject("REVERSE", d, "REVERSAL_WINDOW", txId + " was made on " + tx.date);
        Account from = accounts.get(tx.fromId), to = accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if (from.tier.equals("PREMIUM")) {
            back = back.add(tx.fee);
            if (tx.fee.signum() != 0) stats.addFee(d, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        txs.markAsReversed(txId);
        String newId = txs.add(new Transaction("REVERSE", d, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited, true));
        return accept("REVERSE", d, newId, "reversed " + txId);
    }

    private String checkLimitAndFunds(String d, Account a, BigDecimal amt, BigDecimal fee) {
        BigDecimal limit = a.tier.equals("STANDARD") ? new BigDecimal("5000.00") : a.tier.equals("PREMIUM") ? new BigDecimal("20000.00") : new BigDecimal("50000.00");
        BigDecimal od = a.tier.equals("PREMIUM") ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (usage.get(a.id, d).add(amt).compareTo(limit) > 0) return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier;
        BigDecimal needed = amt.add(fee);
        if (a.balance.subtract(needed).compareTo(od.negate()) < 0) return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + needed + " " + a.currency;
        return null;
    }

    private String accept(String v, String d, String id, String e) {
        stats.count(d, 0); audit.record(v, d, "OK " + id); return "OK " + id + " " + e;
    }

    private String reject(String v, String d, String c, String m) {
        if (d != null) stats.count(d, 1); audit.record(v, d == null ? "????-??-??" : d, "REJECTED " + c); return "REJECTED " + c + ": " + m;
    }
}

